pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint224 amount, address receiver, address nonOwner) public {
        vm.assume(amount > 0);
        vm.assume(receiver != address(0));
        vm.assume(nonOwner != address(this));
        vm.deal(address(c), amount);
        vm.prank(nonOwner);
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Non-owner should be rejected");
    }
